const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Delhi metropolitan area
  const delhi = ee.Geometry.Point([77.2090, 28.6139]).buffer(30000); // 30km radius

  // 2. Define date range for January 15, 2024
  const targetDate = '2024-01-15';
  const startDate = '2024-01-15';
  const endDate = '2024-01-16';

  // 3. Get Sentinel-2 imagery
  let collection = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(delhi)
    .filterDate(startDate, endDate);

  const collectionSize = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collectionSize}`);

  // 4. Check if collection is empty, try Sentinel-2 Cloud Probability
  if (collectionSize === 0) {
    console.log('No Sentinel-2 images found for 2024-01-15');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Get cloud probability data
  const s2Clouds = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
    .filterBounds(delhi)
    .filterDate(startDate, endDate);

  const cloudSize = s2Clouds.size().getInfo();
  console.log(`Cloud probability images found: ${cloudSize}`);

  if (cloudSize === 0) {
    // Fallback: use CLOUD_COVERAGE_ASSESSMENT from Sentinel-2 metadata
    const images = collection.toList(10);
    const firstImage = ee.Image(images.get(0));
    const cloudCoverage = firstImage.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();

    console.log(`Cloud coverage from metadata: ${cloudCoverage.toFixed(2)}%`);

    if (cloudCoverage === null || cloudCoverage === undefined) {
      console.log('Cloud coverage calculation failed');
      console.log('<answer>C3</answer>');
      return;
    }

    // Complete coverage threshold: >95%
    if (cloudCoverage > 95) {
      console.log('Complete cloud coverage confirmed (>95%)');
      console.log('<answer>A</answer>');
    } else {
      console.log('Incomplete cloud coverage (<95%)');
      console.log('<answer>B</answer>');
    }
    return;
  }

  // 6. Calculate average cloud probability over Delhi
  const cloudImage = s2Clouds.mosaic();

  const cloudStats = cloudImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: delhi,
    scale: 1000,
    maxPixels: 1e9
  });

  const meanCloudProb = cloudStats.get('probability').getInfo();

  console.log(`Mean cloud probability: ${meanCloudProb.toFixed(2)}%`);

  if (meanCloudProb === null || meanCloudProb === undefined) {
    console.log('Cloud probability calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Check pixel count
  const pixelCount = cloudImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: delhi,
    scale: 1000,
    maxPixels: 1e9
  }).get('probability').getInfo();

  console.log(`Valid pixels analyzed: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels for analysis');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Final determination: >95% cloud probability = complete coverage
  if (meanCloudProb > 95) {
    console.log('Complete cloud coverage confirmed (>95% probability)');
    console.log('<answer>A</answer>');
  } else {
    console.log('Incomplete cloud coverage (<95% probability)');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
